import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { AdminPagesPage } from './AdminPagesPage';
import { adminWorkspace } from './adminWorkspace';
import { deferred, json, session, viewer } from './adminFixtures.testSupport';
import type { AdminVideoGrid } from './videoGridApi';

const revision = `cr_${'a'.repeat(43)}`, updatedRevision = `cr_${'b'.repeat(43)}`;
const ids = ['111111111111111111111111', '222222222222222222222222'];
/** Complete synthetic public-video snapshot, independent of Page placements. */
const grid = (): AdminVideoGrid => ({ revision, defaultView: 'grid', items: ids.map((id, index) => ({ id, title: ['Morning light', 'Evening light'][index], coverUrl: null, creator: 'Synthetic artist' })) });

/** Answers selected Page reads and records only actual Grid mutations. */
function server() {
  let current = grid(); const writes: Record<string, any>[] = [], reads: string[] = [];
  let write: (body: Record<string, any>) => Response | Promise<Response> = body => {
    current = { ...current, revision: updatedRevision, defaultView: body.defaultView, items: body.videoIds.map((id: string) => current.items.find(item => item.id === id)!) };
    return json({ grid: current, receipt: { operationId: body.operationId } });
  };
  vi.stubGlobal('fetch', vi.fn(async (path: string, init?: RequestInit) => {
    if (path.endsWith('/videos/grid')) {
      if (init?.method === 'PATCH') { const body = JSON.parse(String(init.body)); writes.push(body); return write(body); }
      reads.push(path); return json({ grid: current });
    }
    const slug = path.split('/').at(-1)!; reads.push(path);
    return json({ page: { slug, title: slug, revision, items: slug === 'videos' ? [{ itemId: '333333333333333333333333', referenceId: '444444444444444444444444', itemType: 'grid', order: 0, name: 'Videos', visibility: 'public', sourceMode: 'manual', referenceStatus: 'ready' }] : [] } });
  }));
  return { writes, reads, set: (next: AdminVideoGrid) => { current = next; }, write: (next: typeof write) => { write = next; } };
}
async function mount() {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  await act(async () => render(<QueryClientProvider client={client}><MemoryRouter><AdminPagesPage /></MemoryRouter></QueryClientProvider>));
  await screen.findByRole('button', { name: 'Video' });
  return client;
}
async function openEditor() {
  fireEvent.click(screen.getByRole('button', { name: 'Video' }));
  const opener = await screen.findByRole('button', { name: 'Configure video Grid' });
  await waitFor(() => expect(opener).toBeEnabled()); fireEvent.click(opener);
  const editor = within(await screen.findByRole('region', { name: 'Configure video Grid' }));
  await editor.findByRole('list', { name: 'Draft order' });
  return editor;
}
async function reviewMove() {
  const editor = await openEditor();
  fireEvent.click(editor.getByRole('button', { name: 'Move up Evening light' }));
  fireEvent.change(editor.getByLabelText('Default display'), { target: { value: 'immersive' } });
  fireEvent.click(editor.getByRole('button', { name: 'Save order' }));
  return within(await screen.findByRole('dialog', { name: 'Save video Grid?' }));
}
beforeEach(() => {
  adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('four Page choices expose functional Search and one Video Grid without ineffective placement controls', async () => {
  const api = server(); await mount();
  expect(api.reads).toEqual(['/api/admin/v1/pages/home']);
  fireEvent.click(screen.getByRole('button', { name: 'Search' }));
  expect(await screen.findByText('Search is a functional page. Its results follow each listener’s query and have no configured page items.')).toBeVisible();
  expect(screen.queryByRole('button', { name: 'Adjust order' })).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'Video' }));
  expect(await screen.findByRole('heading', { name: '1 · Video' })).toBeVisible();
  expect(screen.getAllByRole('listitem')).toHaveLength(1);
  expect(screen.queryByRole('button', { name: /Hide this placement/ })).not.toBeInTheDocument();
  expect(screen.queryByRole('button', { name: 'Adjust order' })).not.toBeInTheDocument();
  expect(api.writes).toEqual([]);
});

test('keyboard and button moves edit a local draft and cancellation writes nothing', async () => {
  const api = server(); await mount(); const editor = await openEditor();
  expect(editor.getByRole('button', { name: 'Save order' })).toBeDisabled();
  expect(screen.getByRole('button', { name: 'Search' })).toBeDisabled();
  const handle = editor.getByRole('button', { name: 'Reorder Evening light' }); handle.focus();
  fireEvent.keyDown(handle, { key: 'ArrowUp' });
  expect(within(editor.getByRole('list', { name: 'Draft order' })).getAllByRole('heading').map(heading => heading.textContent)).toEqual(['Evening light', 'Morning light']);
  expect(handle).toHaveFocus();
  fireEvent.click(editor.getByRole('button', { name: 'Move down Evening light' }));
  expect(editor.getByRole('button', { name: 'Save order' })).toBeDisabled();
  fireEvent.change(editor.getByLabelText('Default display'), { target: { value: 'immersive' } });
  expect(editor.getByRole('button', { name: 'Save order' })).toBeEnabled();
  fireEvent.click(editor.getByRole('button', { name: 'Cancel adjustment' }));
  await waitFor(() => expect(screen.queryByRole('region', { name: 'Configure video Grid' })).not.toBeInTheDocument());
  expect(api.writes).toEqual([]);
  expect(screen.getByRole('button', { name: 'Search' })).toBeEnabled();
});

test('the complete order and default display save only after explicit review and restore the editor opener', async () => {
  const api = server(); await mount(); const dialog = await reviewMove();
  expect(api.writes).toEqual([]);
  expect(dialog.getByText('Immersive preview')).toBeVisible();
  expect(within(dialog.getByRole('list', { name: 'New display order' })).getAllByRole('listitem').map(item => item.textContent)).toEqual(['1Evening light', '2Morning light']);
  fireEvent.click(dialog.getByRole('button', { name: 'Confirm save order' }));
  expect(await screen.findByText('Video Grid saved.')).toBeVisible();
  expect(api.writes).toHaveLength(1);
  expect(api.writes[0]).toEqual({ expectedRevision: revision, defaultView: 'immersive', videoIds: [...ids].reverse(), operationId: expect.any(String) });
  await waitFor(() => expect(screen.getByRole('button', { name: 'Configure video Grid' })).toHaveFocus());
});

test('a newer snapshot invalidates the open review and requires fresh adjustment', async () => {
  const api = server(); const client = await mount(); await reviewMove();
  api.set({ ...grid(), revision: updatedRevision });
  await act(async () => { await client.refetchQueries({ predicate: query => query.queryKey.at(-1) === 'video-grid' }); });
  const dialog = within(screen.getByRole('dialog'));
  await waitFor(() => expect(dialog.queryByRole('button', { name: 'Confirm save order' })).not.toBeInTheDocument());
  expect(dialog.getByText('The Video Grid changed. Cancel or refresh and adjust it again before saving.')).toBeVisible();
  fireEvent.click(dialog.getByRole('button', { name: 'Refresh and adjust again' }));
  expect(await screen.findByLabelText('Default display')).toHaveValue('grid');
  expect(screen.getByRole('button', { name: 'Save order' })).toBeDisabled();
  expect(api.writes).toEqual([]);
});

test('an uncertain save keeps its original complete review across refresh and Page switches and retries the same body', async () => {
  const api = server(); api.write(() => json({ message: 'Unavailable' }, 503));
  await mount(); const dialog = await reviewMove();
  fireEvent.click(dialog.getByRole('button', { name: 'Confirm save order' }));
  await screen.findByRole('button', { name: 'Retry original operation' });
  await waitFor(() => expect(screen.getByRole('button', { name: 'Search' })).toBeEnabled());
  const original = api.writes[0];
  api.set({ ...grid(), revision: updatedRevision, items: [{ ...grid().items[0], title: 'Changed elsewhere' }] });
  fireEvent.click(screen.getByRole('button', { name: 'Search' }));
  await screen.findByText('Search is a functional page. Its results follow each listener’s query and have no configured page items.');
  fireEvent.click(screen.getByRole('button', { name: 'Video' }));
  const alert = await screen.findByRole('alert');
  expect(within(alert).getByText('Immersive preview')).toBeVisible();
  expect(within(alert).getByText('Morning light')).toBeVisible();
  expect(within(alert).queryByText('Changed elsewhere')).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Configure video Grid' })).toBeDisabled();
  await waitFor(() => expect(within(alert).getByRole('button', { name: 'Refresh status' })).toBeEnabled());
  fireEvent.click(within(alert).getByRole('button', { name: 'Refresh status' }));
  await waitFor(() => expect(api.reads.filter(path => path.endsWith('/videos/grid')).length).toBeGreaterThan(2));
  api.write(body => json({ grid: grid(), receipt: { operationId: body.operationId } }));
  fireEvent.click(within(alert).getByRole('button', { name: 'Retry original operation' }));
  expect(await screen.findByText('Video Grid saved.')).toBeVisible();
  expect(api.writes[1]).toEqual(original);
});

test('a definite conflict permits refreshing and adjusting but never original-operation retry', async () => {
  const api = server(); api.write(() => json({ code: 'ADMIN_CATALOG_REVISION_CONFLICT' }, 409));
  await mount(); const dialog = await reviewMove(); fireEvent.click(dialog.getByRole('button', { name: 'Confirm save order' }));
  const alert = await screen.findByRole('alert');
  expect(within(alert).getByRole('button', { name: 'Refresh and adjust again' })).toBeEnabled();
  expect(screen.queryByRole('button', { name: 'Retry original operation' })).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Save order' })).toBeDisabled();
});

test('a pending save locks the approval and cannot start another write', async () => {
  const api = server(), pending = deferred<Response>(); api.write(() => pending.promise);
  await mount(); const dialog = await reviewMove(); fireEvent.click(dialog.getByRole('button', { name: 'Confirm save order' }));
  expect(await dialog.findByRole('button', { name: 'Saving order…' })).toBeDisabled();
  expect(dialog.getByRole('button', { name: 'Back to adjustment' })).toBeDisabled();
  fireEvent.keyDown(document, { key: 'Escape' }); expect(screen.getByRole('dialog')).toBeVisible();
  await act(async () => pending.resolve(json({ grid: grid(), receipt: { operationId: api.writes[0].operationId } })));
  expect(await screen.findByText('Video Grid saved.')).toBeVisible();
  expect(api.writes).toHaveLength(1);
});
